const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const body = $input.first().json.body || {};
  const projectId = (body.project_id || '').trim();
  if (!projectId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'project_id requerido' } }];
  return [{ json: { user_id: payload.sub, tenant_id: payload.tenant_id, role: payload.role || 'architect', project_id: projectId, body: body, request_id: 'req_' + Math.random().toString(36).slice(2, 10) }}];
} catch (e) { return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message }}]; }

const sess = $('Decode JWT + Body').first().json;
const projectRows = $('Load Project').all().map(i => i.json).filter(p => p && p.id);
if (projectRows.length === 0) return [{ json: { _error: 'PROJECT_NOT_FOUND', _status: 404, _details: 'project_id no existe', request_id: sess.request_id }}];
const project = projectRows[0];


const incidentText = (sess.body?.incident_description || '').trim();
const monthsSinceDelivery = sess.body?.months_since_delivery || null;
if (!incidentText) return [{ json: { _error: 'NO_INCIDENT', _status: 400, _details: 'falta body.incident_description', request_id: sess.request_id }}];
const systemPrompt = `Eres agent_aftercare. Procesas incidencias post-entrega segun LOE espanola:
- LOE 1 ano: acabados (pintura, rodapies, sellados)
- LOE 3 anos: habitabilidad (humedades, aislamiento, instalaciones)
- LOE 10 anos: estructura (grietas estructurales, asentamientos)
Decide: cubierto_por_LOE (true/false), garantia_aplicable (1y|3y|10y|none), gravedad (low/medium/high/critical), responsable (estudio|gremio|cliente|seguro), accion_inmediata.
DEVUELVE SOLO JSON.`;
const userPrompt = `PROYECTO: ${project.name}
MESES DESDE ENTREGA: ${monthsSinceDelivery ?? '?'}

INCIDENCIA REPORTADA POR EL CLIENTE:
${incidentText}

Triajea.

OUTPUT JSON:
{ "cubierto_por_loe": true, "garantia_aplicable": "3y", "gravedad": "medium", "responsable": "gremio", "accion_inmediata": "...", "plazo_respuesta_dias": 7, "summary": "..." }`;

return [{ json: { user_id: sess.user_id, tenant_id: sess.tenant_id, project_id: project.id, request_id: sess.request_id, body: sess.body, incident_description: $json.body?.incident_description || null, months_since_delivery: $json.body?.months_since_delivery || null, llm_payload: { model: 'gpt-4o', messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt }], temperature: 0.2, max_tokens: 2000, response_format: { type: 'json_object' }}}}];

const llm = $input.first()?.json;
const built = $('Build Prompt').first().json;
const raw = llm?.choices?.[0]?.message?.content || '{}';
let parsed; try { parsed = JSON.parse(raw); } catch (e) { return [{ json: { _error: 'LLM_INVALID_JSON', _status: 502, _details: e.message, _raw: raw.slice(0,500), request_id: built.request_id }}]; }
const usage = llm?.usage || {};
const outputObj = parsed;
const summaryObj = { gravedad: parsed.gravedad, cubierto_por_loe: parsed.cubierto_por_loe, responsable: parsed.responsable };
return [{ json: { user_id: built.user_id, tenant_id: built.tenant_id, project_id: built.project_id, request_id: built.request_id, body: built.body, output: outputObj, summary: summaryObj, model: llm?.model || 'gpt-4o', tokens_in: usage.prompt_tokens || 0, tokens_out: usage.completion_tokens || 0 }}];
